import { type DataClassification } from '@cvg/shared'
import { z } from 'zod'
import {
  type AgentProfileName,
  type Capability,
  type GrantLevel,
  type PolicyProfile,
  type ToolRiskLevel
} from './profile.ts'
import {
  ENGINE_POLICY_ID,
  ENGINE_POLICY_VERSION,
  type PolicyDocument,
  type PolicyEffect,
  type PolicyRule
} from './documents.ts'

export const PolicyDecisionValueSchema = z.enum([
  'ALLOW',
  'DENY',
  'REQUIRE_APPROVAL'
])

export type PolicyDecisionValue = z.infer<typeof PolicyDecisionValueSchema>

export type PolicyEvaluationInput = z.input<
  PolicyProfile['evaluationInputSchema']
>
export type NormalizedPolicyEvaluationInput = z.output<
  PolicyProfile['evaluationInputSchema']
>

export interface PolicyDecision {
  decision: PolicyDecisionValue
  reason: string
  policyId: string
  policyVersion: string
  correlationId: string
  capability: Capability
  risk: ToolRiskLevel
  evaluatedAt: string
}

const CLASSIFICATION_RANK: Record<DataClassification, number> = {
  PUBLIC: 0,
  INTERNAL: 1,
  CONFIDENTIAL: 2,
  CLINICAL: 3,
  FINANCIAL: 4,
  CREDENTIAL: 5
}

const EFFECT_PRECEDENCE: Record<PolicyEffect, number> = {
  ALLOW: 1,
  REQUIRE_APPROVAL: 2,
  DENY: 3
}

export interface PolicyEngineOptions {
  /** Product content: capability catalog, agent profiles and grants. */
  profile: PolicyProfile
  documents?: PolicyDocument[]
  clock?: () => Date
}

/**
 * Deterministic authorization engine. The model has no seat at this table:
 * decisions come exclusively from capability grants, operator role ceilings
 * and versioned policy documents. Missing context or missing tenants deny.
 */
export class PolicyEngine {
  readonly profile: PolicyProfile
  readonly #documents: PolicyDocument[]
  readonly #clock: () => Date

  constructor(options: PolicyEngineOptions) {
    this.profile = options.profile
    this.#documents = options.documents ?? []
    this.#clock = options.clock ?? (() => new Date())
  }

  evaluate(input: PolicyEvaluationInput): PolicyDecision {
    const parsed = this.profile.evaluationInputSchema.safeParse(input)
    if (!parsed.success) {
      return this.#deny(
        'insufficient_context',
        'Policy evaluation received incomplete or invalid context',
        undefined,
        {
          correlationId: safeCorrelation(input),
          capability: this.#safeCapability(input),
          profile: this.#safeProfile(input)
        }
      )
    }
    const request = parsed.data
    const risk = this.profile.risk(request.capability)
    const at = this.#clock()

    if (
      request.resource?.tenantId &&
      request.resource.tenantId !== request.tenantId
    ) {
      return this.#deny(
        'tenant_mismatch',
        'Resource belongs to a different tenant',
        undefined,
        {
          correlationId: request.correlationId,
          capability: request.capability,
          profile: request.agentProfile
        }
      )
    }

    const resourceScope = this.profile.resourceScope(
      request.capability,
      request.resource
    )
    if (resourceScope.status === 'required') {
      return this.#deny(
        'resource_type_required',
        'Capability requires a resource with an explicit type',
        undefined,
        {
          correlationId: request.correlationId,
          capability: request.capability,
          profile: request.agentProfile
        }
      )
    }
    if (resourceScope.status === 'not_allowed') {
      return this.#deny(
        'resource_type_not_allowed',
        'Capability cannot act on this resource type in the controlled scope',
        undefined,
        {
          correlationId: request.correlationId,
          capability: request.capability,
          profile: request.agentProfile
        }
      )
    }

    if (!this.profile.actionMatches(request.capability, request.action)) {
      return this.#deny(
        'action_capability_mismatch',
        'Action is not bound to the requested capability',
        undefined,
        {
          correlationId: request.correlationId,
          capability: request.capability,
          profile: request.agentProfile
        }
      )
    }

    const grant = this.profile.grantFor(
      request.agentProfile,
      request.capability
    )
    if (!grant) {
      return this.#deny(
        'capability_not_granted',
        `Profile ${request.agentProfile} has no grant for ${request.capability}`,
        undefined,
        {
          correlationId: request.correlationId,
          capability: request.capability,
          profile: request.agentProfile
        }
      )
    }

    if (!this.profile.roleAllows(request.operatorRole, request.capability)) {
      return this.#deny(
        'operator_role_denied',
        `Role ${request.operatorRole} cannot exercise ${request.capability}`,
        undefined,
        {
          correlationId: request.correlationId,
          capability: request.capability,
          profile: request.agentProfile
        }
      )
    }

    const matches = this.#matchingRules(request, at)
    const winner = matches[0]

    if (winner) {
      const source = winner.document
      const effect = winner.rule.effect
      if (effect === 'DENY') {
        return this.#decision('DENY', winner.rule.reason, source, request, risk)
      }
      if (effect === 'REQUIRE_APPROVAL') {
        return this.#decision(
          'REQUIRE_APPROVAL',
          winner.rule.reason,
          source,
          request,
          risk
        )
      }
      return this.#decision(
        grant.level === 'require_approval' ? 'REQUIRE_APPROVAL' : 'ALLOW',
        winner.rule.reason,
        source,
        request,
        risk
      )
    }

    return this.#fromGrant(
      request,
      grant.level,
      grant.requiresMedicalOperator === true
    )
  }

  #fromGrant(
    request: NormalizedPolicyEvaluationInput,
    level: GrantLevel,
    requiresMedicalOperator: boolean
  ): PolicyDecision {
    const risk = this.profile.risk(request.capability)
    const emergency = request.context?.emergency === true
    if (
      requiresMedicalOperator &&
      request.context?.medicalOperator !== true &&
      !emergency
    ) {
      return this.#decision(
        'REQUIRE_APPROVAL',
        'Capability requires a medical operator or explicit approval',
        undefined,
        request,
        risk
      )
    }
    if (level === 'require_approval') {
      return this.#decision(
        'REQUIRE_APPROVAL',
        'Capability grant requires human approval',
        undefined,
        request,
        risk
      )
    }
    if (risk === 'HIGH_RISK_WRITE' || risk === 'ADMIN') {
      return this.#decision(
        'REQUIRE_APPROVAL',
        'High-risk capability always requires human approval',
        undefined,
        request,
        risk
      )
    }
    return this.#decision(
      'ALLOW',
      'Capability granted by least-privilege profile',
      undefined,
      request,
      risk
    )
  }

  #matchingRules(
    request: NormalizedPolicyEvaluationInput,
    at: Date
  ): Array<{ rule: PolicyRule; document: PolicyDocument }> {
    const classification =
      request.context?.dataClassification !== undefined
        ? CLASSIFICATION_RANK[request.context.dataClassification]
        : 0
    const winners: Array<{ rule: PolicyRule; document: PolicyDocument }> = []
    for (const document of this.#documents) {
      if (
        document.tenantId !== undefined &&
        document.tenantId !== request.tenantId
      ) {
        continue
      }
      if (at.getTime() < Date.parse(document.effectiveFrom)) continue
      if (
        document.effectiveUntil &&
        at.getTime() > Date.parse(document.effectiveUntil)
      ) {
        continue
      }
      for (const rule of document.rules) {
        if (ruleAppliesTo(rule, request, classification)) {
          winners.push({ rule, document })
        }
      }
    }
    winners.sort((left, right) => {
      if (right.rule.priority !== left.rule.priority) {
        return right.rule.priority - left.rule.priority
      }
      return (
        EFFECT_PRECEDENCE[right.rule.effect] -
        EFFECT_PRECEDENCE[left.rule.effect]
      )
    })
    return winners
  }

  #decision(
    decision: PolicyDecisionValue,
    reason: string,
    source: PolicyDocument | undefined,
    request: NormalizedPolicyEvaluationInput,
    risk: ToolRiskLevel
  ): PolicyDecision {
    return {
      decision,
      reason,
      policyId: source?.policyId ?? ENGINE_POLICY_ID,
      policyVersion: source?.version ?? ENGINE_POLICY_VERSION,
      correlationId: request.correlationId,
      capability: request.capability,
      risk,
      evaluatedAt: this.#clock().toISOString()
    }
  }

  #deny(
    reason: string,
    _message: string,
    policyId: string | undefined,
    fallback: {
      correlationId: string
      capability: Capability
      profile: AgentProfileName
    }
  ): PolicyDecision {
    return {
      decision: 'DENY',
      reason,
      policyId: policyId ?? ENGINE_POLICY_ID,
      policyVersion: ENGINE_POLICY_VERSION,
      correlationId: fallback.correlationId,
      capability: fallback.capability,
      risk: this.profile.catalog[fallback.capability]
        ? this.profile.catalog[fallback.capability]!.risk
        : 'ADMIN',
      evaluatedAt: this.#clock().toISOString()
    }
  }

  listProfiles(): AgentProfileName[] {
    return this.profile.agentProfileNames()
  }

  #safeCapability(input: unknown): Capability {
    if (input && typeof input === 'object') {
      const value = (input as { capability?: unknown }).capability
      const parsed = this.profile.capabilitySchema.safeParse(value)
      if (parsed.success) return parsed.data
    }
    return this.profile.invalidCapabilityFallback
  }

  #safeProfile(input: unknown): AgentProfileName {
    if (input && typeof input === 'object') {
      const value = (input as { agentProfile?: unknown }).agentProfile
      const parsed = this.profile.agentProfileSchema.safeParse(value)
      if (parsed.success) return parsed.data
    }
    return 'unknown'
  }
}

function ruleAppliesTo(
  rule: PolicyRule,
  request: NormalizedPolicyEvaluationInput,
  classificationRank: number
): boolean {
  if (rule.capabilities && !rule.capabilities.includes(request.capability)) {
    return false
  }
  if (
    rule.agentProfiles &&
    !rule.agentProfiles.includes(request.agentProfile)
  ) {
    return false
  }
  if (rule.roles && !rule.roles.includes(request.operatorRole)) {
    return false
  }
  if (rule.actions && !rule.actions.includes(request.action)) {
    return false
  }
  if (
    rule.resourceTypes &&
    (!request.resource || !rule.resourceTypes.includes(request.resource.type))
  ) {
    return false
  }
  if (rule.classificationAtLeast) {
    const minimum = CLASSIFICATION_RANK[rule.classificationAtLeast]
    if (classificationRank < minimum) return false
  }
  return true
}

function safeCorrelation(input: unknown): string {
  if (input && typeof input === 'object') {
    const value = (input as { correlationId?: unknown }).correlationId
    if (typeof value === 'string' && value.length >= 8) return value
  }
  return 'corr_unknown'
}

import { z } from 'zod'
import { DataClassificationSchema, RoleSchema } from '@cvg/shared'

/**
 * SPEC-LEGACY-002 — the policy engine owns the mechanism; a product supplies
 * the content (capability catalog, agent profiles, grants and role ceilings)
 * as a PolicyProfile. Every set is closed per profile: a capability or agent
 * profile the profile does not declare fails schema validation, exactly as a
 * value outside the former built-in enums did.
 */

export const CapabilityNameSchema = z
  .string()
  .regex(/^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$/)
export type Capability = string

export const AgentProfileIdSchema = z.string().regex(/^[a-z][a-z0-9_-]*$/)
export type AgentProfileName = string

export const ToolRiskLevelSchema = z.enum([
  'READ_ONLY',
  'LOW_RISK_WRITE',
  'MEDIUM_RISK_WRITE',
  'HIGH_RISK_WRITE',
  'ADMIN'
])
export type ToolRiskLevel = z.infer<typeof ToolRiskLevelSchema>

export const GrantLevelSchema = z.enum(['allow', 'require_approval'])
export type GrantLevel = z.infer<typeof GrantLevelSchema>

export const RoleNameSchema = RoleSchema
export type RoleName = z.infer<typeof RoleNameSchema>

export interface CapabilityDefinition {
  capability: Capability
  category: string
  risk: ToolRiskLevel
  description: string
}

export interface CapabilityGrant {
  capability: Capability
  level: GrantLevel
  limitedFields?: boolean
  requiresMedicalOperator?: boolean
}

export type ResourceTypeScope =
  | { status: 'not_scoped' }
  | { status: 'required' }
  | { status: 'not_allowed' }
  | { status: 'allowed' }

export interface PolicyProfileInput {
  /** Stable identifier of the product profile, for diagnostics. */
  id: string
  catalog: Readonly<Record<Capability, CapabilityDefinition>>
  /**
   * Explicit action identifiers per capability. Closed and exhaustive: every
   * catalog capability declares its actions.
   */
  actions: Readonly<Record<Capability, readonly string[]>>
  /** Resource-type applicability for effect capabilities. */
  resourceTypes?: Readonly<Record<Capability, readonly string[]>>
  /** Capability ceiling per agent profile. Absence is DENY. */
  agentProfileGrants: Readonly<
    Record<AgentProfileName, readonly CapabilityGrant[]>
  >
  /** Operator role ceiling. */
  operatorRoleCapabilities: Readonly<Record<RoleName, readonly Capability[]>>
  approverRoles: readonly RoleName[]
  /**
   * Capability reported on a DENY for input that could not be parsed. It must
   * belong to the catalog.
   */
  invalidCapabilityFallback: Capability
}

export interface PolicyProfile {
  readonly id: string
  readonly catalog: Readonly<Record<Capability, CapabilityDefinition>>
  readonly actions: Readonly<Record<Capability, readonly string[]>>
  readonly resourceTypes: Readonly<Record<Capability, readonly string[]>>
  readonly agentProfileGrants: Readonly<
    Record<AgentProfileName, readonly CapabilityGrant[]>
  >
  readonly operatorRoleCapabilities: Readonly<
    Record<RoleName, readonly Capability[]>
  >
  readonly approverRoles: readonly RoleName[]
  readonly invalidCapabilityFallback: Capability
  /** Closed schema over the catalog capability names. */
  readonly capabilitySchema: ClosedSchema
  /** Closed schema over the declared agent profile names. */
  readonly agentProfileSchema: ClosedSchema
  readonly grantSchema: ReturnType<typeof createGrantSchema>
  readonly policyRuleSchema: ReturnType<typeof createPolicyRuleSchema>
  readonly policyDocumentSchema: ReturnType<typeof createPolicyDocumentSchema>
  readonly evaluationInputSchema: ReturnType<typeof createEvaluationInputSchema>
  agentProfileNames(): AgentProfileName[]
  risk(capability: Capability): ToolRiskLevel
  isHighRisk(capability: Capability): boolean
  resourceScope(
    capability: Capability,
    resource: { type?: string } | undefined
  ): ResourceTypeScope
  actionMatches(capability: Capability, action: string): boolean
  grantFor(
    profile: AgentProfileName,
    capability: Capability
  ): CapabilityGrant | undefined
  roleAllows(role: RoleName, capability: Capability): boolean
  canApprove(role: RoleName, capability: Capability): boolean
}

export class PolicyProfileError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'PolicyProfileError'
  }
}

export function riskRequiresApproval(risk: ToolRiskLevel): boolean {
  return risk === 'HIGH_RISK_WRITE' || risk === 'ADMIN'
}

type ClosedSchema = z.ZodEnum<Record<string, string>>

function closedSchema(values: readonly string[], label: string): ClosedSchema {
  if (values.length === 0) {
    throw new PolicyProfileError(`${label} must not be empty`)
  }
  return z.enum(values as [string, ...string[]])
}

function createGrantSchema(capabilitySchema: ClosedSchema) {
  return z.object({
    capability: capabilitySchema,
    level: GrantLevelSchema,
    limitedFields: z.boolean().optional(),
    requiresMedicalOperator: z.boolean().optional()
  })
}

function createPolicyRuleSchema(
  capabilitySchema: ClosedSchema,
  agentProfileSchema: ClosedSchema
) {
  return z
    .object({
      id: z.string().min(1).max(120),
      effect: z.enum(['ALLOW', 'DENY', 'REQUIRE_APPROVAL']),
      priority: z.number().int().min(-100).max(100).default(0),
      capabilities: z.array(capabilitySchema).min(1).optional(),
      agentProfiles: z.array(agentProfileSchema).min(1).optional(),
      roles: z.array(RoleNameSchema).min(1).optional(),
      actions: z.array(z.string().min(1).max(120)).min(1).optional(),
      resourceTypes: z.array(z.string().min(1).max(120)).min(1).optional(),
      /** Rule applies when the request classification rank is >= this value. */
      classificationAtLeast: DataClassificationSchema.optional(),
      reason: z.string().min(1).max(240)
    })
    .strict()
}

function createPolicyDocumentSchema(
  ruleSchema: ReturnType<typeof createPolicyRuleSchema>
) {
  return z
    .object({
      policyId: z.string().min(1).max(120),
      version: z.string().min(1).max(60),
      tenantId: z.string().min(1).max(120).optional(),
      effectiveFrom: z.string().datetime(),
      effectiveUntil: z.string().datetime().optional(),
      rules: z.array(ruleSchema).min(1)
    })
    .strict()
}

function createEvaluationInputSchema(
  capabilitySchema: ClosedSchema,
  agentProfileSchema: ClosedSchema
) {
  return z
    .object({
      tenantId: z.string().min(1).max(120),
      operatorId: z.string().min(1).max(120),
      operatorRole: RoleSchema,
      agentId: z.string().min(1).max(120),
      agentProfile: agentProfileSchema,
      capability: capabilitySchema,
      action: z.string().min(1).max(120),
      correlationId: z.string().min(8).max(120),
      resource: z
        .object({
          type: z.string().min(1).max(120),
          id: z.string().min(1).max(160).optional(),
          tenantId: z.string().min(1).max(120).optional()
        })
        .strict()
        .optional(),
      context: z
        .object({
          dataClassification: DataClassificationSchema.optional(),
          emergency: z.boolean().optional(),
          medicalOperator: z.boolean().optional()
        })
        .strict()
        .optional()
    })
    .strict()
}

/**
 * Validates a product profile and derives its closed schemas and lookups.
 * Every reference (grants, role ceilings, actions, resource types, fallback)
 * must point at a declared capability; otherwise the profile is rejected.
 */
export function createPolicyProfile(input: PolicyProfileInput): PolicyProfile {
  const capabilityNames = Object.keys(input.catalog)
  for (const name of capabilityNames) {
    if (!CapabilityNameSchema.safeParse(name).success) {
      throw new PolicyProfileError(`Invalid capability name: ${name}`)
    }
    const definition = input.catalog[name]
    if (!definition || definition.capability !== name) {
      throw new PolicyProfileError(`Catalog entry ${name} is inconsistent`)
    }
    if (!input.actions[name] || input.actions[name].length === 0) {
      throw new PolicyProfileError(`Capability ${name} declares no action`)
    }
  }
  const known = new Set(capabilityNames)
  const requireKnown = (capability: string, where: string): void => {
    if (!known.has(capability)) {
      throw new PolicyProfileError(`${where} references unknown ${capability}`)
    }
  }
  for (const name of Object.keys(input.actions)) requireKnown(name, 'actions')
  for (const name of Object.keys(input.resourceTypes ?? {})) {
    requireKnown(name, 'resourceTypes')
  }
  const profileNames = Object.keys(input.agentProfileGrants)
  for (const name of profileNames) {
    if (!AgentProfileIdSchema.safeParse(name).success) {
      throw new PolicyProfileError(`Invalid agent profile name: ${name}`)
    }
    for (const grant of input.agentProfileGrants[name] ?? []) {
      requireKnown(grant.capability, `profile ${name}`)
    }
  }
  for (const [role, capabilities] of Object.entries(
    input.operatorRoleCapabilities
  )) {
    for (const capability of capabilities) {
      requireKnown(capability, `role ${role}`)
    }
  }
  requireKnown(input.invalidCapabilityFallback, 'invalidCapabilityFallback')

  const capabilitySchema = closedSchema(capabilityNames, 'catalog')
  const agentProfileSchema = closedSchema(profileNames, 'agentProfileGrants')
  const policyRuleSchema = createPolicyRuleSchema(
    capabilitySchema,
    agentProfileSchema
  )
  const resourceTypes = Object.freeze({ ...(input.resourceTypes ?? {}) })

  const profile: PolicyProfile = {
    id: input.id,
    catalog: input.catalog,
    actions: input.actions,
    resourceTypes,
    agentProfileGrants: input.agentProfileGrants,
    operatorRoleCapabilities: input.operatorRoleCapabilities,
    approverRoles: input.approverRoles,
    invalidCapabilityFallback: input.invalidCapabilityFallback,
    capabilitySchema,
    agentProfileSchema,
    grantSchema: createGrantSchema(capabilitySchema),
    policyRuleSchema,
    policyDocumentSchema: createPolicyDocumentSchema(policyRuleSchema),
    evaluationInputSchema: createEvaluationInputSchema(
      capabilitySchema,
      agentProfileSchema
    ),
    agentProfileNames: () => [...profileNames],
    risk(capability) {
      const definition = input.catalog[capability]
      if (!definition) {
        throw new PolicyProfileError(`Unknown capability ${capability}`)
      }
      return definition.risk
    },
    isHighRisk(capability) {
      return riskRequiresApproval(profile.risk(capability))
    },
    resourceScope(capability, resource) {
      const allowed = resourceTypes[capability]
      if (!allowed) return { status: 'not_scoped' }
      if (!resource || typeof resource.type !== 'string') {
        return { status: 'required' }
      }
      return allowed.includes(resource.type)
        ? { status: 'allowed' }
        : { status: 'not_allowed' }
    },
    actionMatches(capability, action) {
      return input.actions[capability]?.includes(action) ?? false
    },
    grantFor(agentProfile, capability) {
      return input.agentProfileGrants[agentProfile]?.find(
        (grant) => grant.capability === capability
      )
    },
    roleAllows(role, capability) {
      return input.operatorRoleCapabilities[role]?.includes(capability) ?? false
    },
    canApprove(role, capability) {
      if (!input.approverRoles.includes(role)) return false
      if (role === 'Operator') return false
      return profile.roleAllows(role, capability)
    }
  }
  return Object.freeze(profile)
}

import { z } from 'zod'
import type { PolicyProfile } from './profile.ts'

export const PolicyEffectSchema = z.enum(['ALLOW', 'DENY', 'REQUIRE_APPROVAL'])
export type PolicyEffect = z.infer<typeof PolicyEffectSchema>

/** Policy documents are validated by `PolicyProfile.policyDocumentSchema`. */
export type PolicyRule = z.output<PolicyProfile['policyRuleSchema']>
export type PolicyRuleInput = z.input<PolicyProfile['policyRuleSchema']>

export type PolicyDocument = z.output<PolicyProfile['policyDocumentSchema']>
export type PolicyDocumentInput = z.input<PolicyProfile['policyDocumentSchema']>

export const ENGINE_POLICY_ID = 'builtin.deny_by_default'
export const ENGINE_POLICY_VERSION = 'policy-engine-v1'

export function policyDocumentKey(policyId: string, version: string): string {
  return `${policyId}@${version}`
}

export class PolicyRegistryError extends Error {
  readonly code: 'policy_duplicate' | 'policy_unknown'

  constructor(code: PolicyRegistryError['code'], message: string) {
    super(message)
    this.name = 'PolicyRegistryError'
    this.code = code
  }
}

/**
 * Versioned policy document registry. Tenant documents are additive with global
 * documents; a tenant document can only make decisions stricter because rule
 * resolution takes the most restrictive matching effect.
 */
export class PolicyRegistry {
  readonly #documents = new Map<string, PolicyDocument>()
  readonly #profile: PolicyProfile

  /** Documents are validated against the capabilities of `profile`. */
  constructor(profile: PolicyProfile) {
    this.#profile = profile
  }

  register(input: PolicyDocumentInput): PolicyDocument {
    const parsed = this.#profile.policyDocumentSchema.parse(input)
    const key = policyDocumentKey(parsed.policyId, parsed.version)
    const existing = this.#documents.get(key)
    if (existing) {
      if (JSON.stringify(existing) !== JSON.stringify(parsed)) {
        throw new PolicyRegistryError(
          'policy_duplicate',
          `Policy ${key} is already registered with different content`
        )
      }
      return existing
    }
    this.#documents.set(key, parsed)
    return parsed
  }

  get(policyId: string, version: string): PolicyDocument | undefined {
    return this.#documents.get(policyDocumentKey(policyId, version))
  }

  list(): PolicyDocument[] {
    return [...this.#documents.values()]
  }

  effectiveFor(input: { tenantId: string; at: Date }): PolicyDocument[] {
    return this.list().filter((document) => {
      if (
        document.tenantId !== undefined &&
        document.tenantId !== input.tenantId
      ) {
        return false
      }
      if (input.at.getTime() < Date.parse(document.effectiveFrom)) return false
      if (
        document.effectiveUntil &&
        input.at.getTime() > Date.parse(document.effectiveUntil)
      ) {
        return false
      }
      return true
    })
  }
}

import { describe, expect, it } from 'vitest'
import { PolicyRegistry } from '../documents.ts'
import { PolicyEngine } from '../engine.ts'
import {
  PolicyProfileError,
  createPolicyProfile,
  type PolicyProfileInput
} from '../profile.ts'

// SPEC-LEGACY-002 slice 1: the engine mechanism works with any product
// profile. This minimal neutral profile carries no legacy vocabulary.
function baseInput(): PolicyProfileInput {
  return {
    id: 'test.minimal',
    catalog: {
      'record.read': {
        capability: 'record.read',
        category: 'record',
        risk: 'READ_ONLY',
        description: 'Read a record'
      },
      'record.update': {
        capability: 'record.update',
        category: 'record',
        risk: 'HIGH_RISK_WRITE',
        description: 'Update a record'
      }
    },
    actions: {
