function cloneRecord(record: ApprovalRecord): ApprovalRecord {
  return structuredClone(record)
}

function recordsEquivalent(
  left: ApprovalRecord,
  right: ApprovalRecord
): boolean {
  // Both records derive from the same mapper column order, so key order is a
  // stable comparison basis; a semantic difference always changes the JSON.
  return JSON.stringify(left) === JSON.stringify(right)
}

/**
 * PostgreSQL incarnation of `ApprovalAuthority` (PROD-04, architecture A2).
 *
 * The canonical decision state machine is not duplicated: every operation
 * loads the affected record(s) `FOR UPDATE` inside one `withTenantTransaction`,
 * seeds a scratch `InMemoryApprovalStore`, runs the same synchronous
 * `ApprovalEngine` method and persists the resulting record(s) with a
 * compare-and-set on revision, status, reservation id and reservation
 * generation. SQL serializes writers; the engine remains the only authority
 * that decides transitions.
 */
export class PostgresApprovalAuthority implements ApprovalAuthority {
  readonly #pool: PostgresPoolLike
  readonly #clock: () => Date
  readonly #engineOptions: Omit<ApprovalEngineOptions, 'store'>

  constructor(
    pool: PostgresPoolLike,
    options: PostgresApprovalAuthorityOptions = {}
  ) {
    this.#pool = pool
    const engineOptions = options.engine ?? {}
    this.#clock = options.clock ?? engineOptions.clock ?? (() => new Date())
    this.#engineOptions = { ...engineOptions, clock: this.#clock }
  }

  async request(input: ApprovalRequestInput): Promise<ApprovalRecord> {
    return withTenantTransaction(this.#pool, input.tenantId, async (client) => {
      const engine = this.#createEngine(new InMemoryApprovalStore())
      const record = engine.request(input)
      await this.#insert(client, record)
      return record
    })
  }

  submit(
    tenantId: string,
    approvalId: string,
    actorId: string
  ): Promise<ApprovalRecord> {
    return this.#mutateRecord(tenantId, approvalId, (engine) =>
      engine.submit(tenantId, approvalId, actorId)
    )
  }

  approve(
    tenantId: string,
    approvalId: string,
    input: ApprovalDecisionInput
  ): Promise<ApprovalRecord> {
    return this.#mutateRecord(tenantId, approvalId, (engine) =>
      engine.approve(tenantId, approvalId, input)
    )
  }

  reject(
    tenantId: string,
    approvalId: string,
    input: ApprovalDecisionInput
  ): Promise<ApprovalRecord> {
    return this.#mutateRecord(tenantId, approvalId, (engine) =>
      engine.reject(tenantId, approvalId, input)
    )
  }

  cancel(
    tenantId: string,
    approvalId: string,
    actorId: string
  ): Promise<ApprovalRecord> {
    return this.#mutateRecord(tenantId, approvalId, (engine) =>
      engine.cancel(tenantId, approvalId, actorId)
    )
  }

  verifyAndConsume(input: {
    tenantId: string
    approvalId: string
    action: string
    resource: { type: string; id?: string }
    payload: unknown
    executionRef?: string
  }): Promise<ApprovalConsumption> {
    return this.#mutateRecord(input.tenantId, input.approvalId, (engine) =>
      engine.verifyAndConsume(input)
    )
  }

  reserve(input: ApprovalReserveInput): Promise<ApprovalReservation> {
    return this.#mutateRecord(input.tenantId, input.approvalId, (engine) =>
      engine.reserve(input)
    )
  }

  markExecuting(input: {
    tenantId: string
    approvalId: string
    reservationId: string
  }): Promise<ApprovalRecord> {
    return this.#mutateRecord(input.tenantId, input.approvalId, (engine) =>
      engine.markExecuting(input)
    )
  }

  confirm(input: {
    tenantId: string
    approvalId: string
    reservationId: string
    evidence: EffectEvidence
  }): Promise<ApprovalRecord> {
    return this.#mutateRecord(input.tenantId, input.approvalId, (engine) =>
      engine.confirm(input)
    )
  }

  release(input: {
    tenantId: string
    approvalId: string
    reservationId: string
    evidence: EffectEvidence
  }): Promise<ApprovalRecord> {
    return this.#mutateRecord(input.tenantId, input.approvalId, (engine) =>
      engine.release(input)
    )
  }

  fail(input: {
    tenantId: string
    approvalId: string
    reservationId: string
    evidence: EffectEvidence
  }): Promise<ApprovalRecord> {
    return this.#mutateRecord(input.tenantId, input.approvalId, (engine) =>
      engine.fail(input)
    )
  }

  markUncertain(input: {
    tenantId: string
    approvalId: string
    reservationId: string
    reason: string
    evidence?: EffectEvidence
  }): Promise<ApprovalRecord> {
    return this.#mutateRecord(input.tenantId, input.approvalId, (engine) =>
      engine.markUncertain(input)
    )
  }

  reconcile(input: {
    tenantId: string
    approvalId: string
    actorId: string
    evidence: EffectEvidence
  }): Promise<ApprovalRecord> {
    return this.#mutateRecord(input.tenantId, input.approvalId, (engine) =>
      engine.reconcile(input)
    )
  }

  async releaseExpired(input: {
    tenantId: string
    now?: Date
    ttlMs?: number
    evidenceFor: (record: ApprovalRecord) => EffectEvidence | undefined
  }): Promise<{ released: number; uncertain: number }> {
    return withTenantTransaction(this.#pool, input.tenantId, async (client) => {
      const now = input.now ?? this.#clock()
      const result = await client.query<RuntimeApprovalRow>(
        `SELECT ${runtimeApprovalColumns}
         FROM runtime_approvals
         WHERE tenant_id = $1
           AND status IN ('RESERVED', 'EXECUTING')
           AND reservation_expires_at IS NOT NULL
           AND reservation_expires_at <= $2
         ORDER BY approval_id
         FOR UPDATE`,
        [input.tenantId, now]
      )
      const loaded = new Map<string, LoadedApproval>()
      const store = new InMemoryApprovalStore()
      for (const row of result.rows) {
        const record = mapRuntimeApprovalRow(row)
        loaded.set(record.approvalId, {
          record,
          revision: Number(row.revision)
        })
        store.insert(cloneRecord(record))
      }
      const engine = this.#createEngine(store)
      const sweep = engine.releaseExpired({ ...input, now })
      await this.#persistChanged(client, loaded, store, input.tenantId)
      return sweep
    })
  }

  /**
   * The engine sweep is cross-tenant (`store.listExpiringBefore` has no tenant
   * filter) while every durable connection carries exactly one
   * `cvg.tenant_id`. The durable authority fails closed instead of pretending
   * the RLS scope can cover every tenant; production sweeps per tenant through
   * `releaseExpired`.
   */
  expireStale(): Promise<never> {
    return Promise.reject(
      new DomainError(
        'invalid_action',
        'expireStale is unsupported by PostgresApprovalAuthority: the engine sweep is cross-tenant while every durable connection is scoped by PostgreSQL RLS to one cvg.tenant_id. Sweep each tenant with releaseExpired.'
      )
    )
  }

  async list(
    tenantId: string,
    status?: ApprovalStatus
  ): Promise<ApprovalRecord[]> {
    return withTenantContext(this.#pool, tenantId, async (client) => {
      const result =
        status === undefined
          ? await client.query<RuntimeApprovalRow>(
              `SELECT ${runtimeApprovalColumns}
               FROM runtime_approvals
               WHERE tenant_id = $1
               ORDER BY requested_at, approval_id`,
              [tenantId]
            )
          : await client.query<RuntimeApprovalRow>(
              `SELECT ${runtimeApprovalColumns}
               FROM runtime_approvals
               WHERE tenant_id = $1 AND status = $2
               ORDER BY requested_at, approval_id`,
              [tenantId, status]
            )
      return result.rows.map(mapRuntimeApprovalRow)
    })
  }

  async get(tenantId: string, approvalId: string): Promise<ApprovalRecord> {
    const record = await withTenantContext(
      this.#pool,
      tenantId,
      async (client) => {
        const result = await client.query<RuntimeApprovalRow>(
          `SELECT ${runtimeApprovalColumns}
           FROM runtime_approvals
           WHERE tenant_id = $1 AND approval_id = $2`,
          [tenantId, approvalId]
        )
        const row = result.rows[0]
        return row ? mapRuntimeApprovalRow(row) : undefined
      }
    )
    if (record === undefined) {
      throw new ApprovalError('not_found', 'Approval not found for this tenant')
    }
    return record
  }

  /** Approvals still awaiting an operator decision (REQUESTED or PENDING). */
  async listPending(tenantId: string): Promise<ApprovalRecord[]> {
    return withTenantContext(this.#pool, tenantId, async (client) => {
      const result = await client.query<RuntimeApprovalRow>(
        `SELECT ${runtimeApprovalColumns}
         FROM runtime_approvals
         WHERE tenant_id = $1 AND status IN ('REQUESTED', 'PENDING')
         ORDER BY requested_at, approval_id`,
        [tenantId]
      )
      return result.rows.map(mapRuntimeApprovalRow)
    })
  }

  /**
   * Returns every candidate sharing the operation key. The key is not unique:
   * the effect journal (0013) is the authority that binds a key to a single
   * effect, so callers must reconcile candidates explicitly.
   */
  async getByOperationKey(
    tenantId: string,
    operationKey: string
  ): Promise<ApprovalRecord[]> {
    return withTenantContext(this.#pool, tenantId, async (client) => {
      const result = await client.query<RuntimeApprovalRow>(
        `SELECT ${runtimeApprovalColumns}
         FROM runtime_approvals
         WHERE tenant_id = $1 AND operation_key = $2
         ORDER BY requested_at, approval_id`,
        [tenantId, operationKey]
      )
      return result.rows.map(mapRuntimeApprovalRow)
    })
  }

  #createEngine(store: InMemoryApprovalStore): ApprovalEngine {
    return new ApprovalEngine({ ...this.#engineOptions, store })
  }

  async #mutateRecord<T>(
    tenantId: string,
    approvalId: string,
    run: (engine: ApprovalEngine, loaded: LoadedApproval) => T
  ): Promise<T> {
    const outcome = await withTenantTransaction(
      this.#pool,
      tenantId,
      async (client) => {
        const loaded = await this.#selectForUpdate(client, tenantId, approvalId)
        if (loaded === undefined) {
          throw new ApprovalError(
            'not_found',
            'Approval not found for this tenant'
          )
        }
        const store = new InMemoryApprovalStore()
        store.insert(cloneRecord(loaded.record))
        const engine = this.#createEngine(store)
        const loadedById = new Map([[approvalId, loaded]])
        try {
          const value = run(engine, loaded)
          await this.#persistChanged(client, loadedById, store, tenantId)
          return { ok: true as const, value }
        } catch (error) {
          // The engine expiry guard marks the record EXPIRED before throwing
          // `expired`. Committing that transition and then rethrowing keeps the
          // durable record equal to the in-memory state machine.
          await this.#persistChanged(client, loadedById, store, tenantId)
          return { ok: false as const, error }
        }
      }
    )
    if (!outcome.ok) throw outcome.error
    return outcome.value
  }

  async #selectForUpdate(
    client: PostgresPoolClient,
    tenantId: string,
    approvalId: string
  ): Promise<LoadedApproval | undefined> {
    const result = await client.query<RuntimeApprovalRow>(
      `SELECT ${runtimeApprovalColumns}
       FROM runtime_approvals
       WHERE tenant_id = $1 AND approval_id = $2
       FOR UPDATE`,
      [tenantId, approvalId]
    )
    const row = result.rows[0]
    return row
      ? { record: mapRuntimeApprovalRow(row), revision: Number(row.revision) }
      : undefined
  }

  async #persistChanged(
    client: PostgresPoolClient,
    loaded: Map<string, LoadedApproval>,
    store: InMemoryApprovalStore,
    tenantId: string
  ): Promise<number> {
    let persisted = 0
    for (const [approvalId, original] of loaded) {
      const current = store.get(tenantId, approvalId)
      if (current === undefined) continue
      if (recordsEquivalent(original.record, current)) continue
      const updated = await this.#compareAndSet(client, original, current)
      if (!updated) {
        throw new DomainError(
          'conflict',
          `Approval ${approvalId} compare-and-set failed`
        )
      }
      persisted += 1
    }
    return persisted
  }

  async #compareAndSet(
    client: PostgresPoolClient,
    loaded: LoadedApproval,
    next: ApprovalRecord
  ): Promise<boolean> {
    const values = recordValues(next)
    const mutable = values.slice(2)
    const updatedAt = this.#clock().toISOString()
    const result = await client.query(
      `UPDATE runtime_approvals
       SET ${casSetClause},
           revision = revision + 1,
           updated_at = $${casUpdatedAtParam}
       WHERE tenant_id = $1
         AND approval_id = $2
         AND revision = $${casRevisionParam}
         AND status = $${casStatusParam}
         AND COALESCE(reservation_id, '') = $${casReservationIdParam}
         AND reservation_generation = $${casGenerationParam}
       RETURNING revision`,
      [
        loaded.record.tenantId,
        loaded.record.approvalId,
        ...mutable,
        updatedAt,
        loaded.revision,
        loaded.record.status,
        loaded.record.reservationId ?? '',
        loaded.record.reservationGeneration ?? 0
      ]
    )
    return (result.rowCount ?? 0) === 1
  }

  async #insert(
    client: PostgresPoolClient,
    record: ApprovalRecord
  ): Promise<void> {
    const createdAt = this.#clock().toISOString()
    await client.query(
      `INSERT INTO runtime_approvals (${insertColumns})
       VALUES (${insertPlaceholders}, 1, $${persistedColumns.length + 1}, $${persistedColumns.length + 1})`,
      [...recordValues(record), createdAt]
    )
  }
}

import {
  approvalMatchesAction,
  type ApprovalAuthority,
  type ApprovalRecord
} from '@cvg/approval-engine'
import type {
  ApprovalDecision,
  ApprovalEngine,
  ApprovalId,
  ApprovalExecutionHandle,
  ApprovalExecutionPort,
  ApprovalExecutionRequest,
  ApprovalRequest
} from '@cvg/harness-contracts'

export interface DurableApprovalAdapterOptions {
  readonly defaultOperatorId?: string
  readonly defaultPolicyVersion?: string
}

/**
 * Bridges the neutral harness approval port to the durable ApprovalAuthority.
 * The authority remains the only state-machine decision maker; this adapter
 * only performs idempotent lookup, canonical binding checks, and translation
 * to the neutral runtime contract.
 */
export class DurableApprovalEngineAdapter implements ApprovalEngine {
  private readonly defaultOperatorId: string
  private readonly defaultPolicyVersion: string
  private readonly requestLocks = new Map<string, Promise<void>>()

  public readonly execution: ApprovalExecutionPort = {
    begin: (request) => this.beginExecution(request),
    complete: (input) => this.completeExecution(input),
    fail: (input) => this.failExecution(input),
    uncertain: (input) => this.markUncertain(input)
  }

  public constructor(
    public readonly authority: ApprovalAuthority,
    options: DurableApprovalAdapterOptions = {}
  ) {
    this.defaultOperatorId = options.defaultOperatorId ?? 'system.execution'
    this.defaultPolicyVersion = options.defaultPolicyVersion ?? 'unknown'
  }

  public async request(input: ApprovalRequest): Promise<ApprovalDecision> {
    const lockKey = [
      input.tenantId,
      input.executionRef ?? '',
      input.operationKey
    ].join('\u0000')
    const previous = this.requestLocks.get(lockKey) ?? Promise.resolve()
    let release!: () => void
    const current = new Promise<void>((resolve) => {
      release = resolve
    })
    const chain = previous.then(() => current)
    this.requestLocks.set(lockKey, chain)
    await previous
    try {
      return await this.requestUnserialized(input)
    } finally {
      release()
      if (this.requestLocks.get(lockKey) === chain) {
        this.requestLocks.delete(lockKey)
      }
    }
  }

  private async requestUnserialized(
    input: ApprovalRequest
  ): Promise<ApprovalDecision> {
    if (!input.executionRef) {
      throw new Error(
        'Durable operational approval requires an execution reference.'
      )
    }
    const operatorId = input.operatorId ?? this.defaultOperatorId
    const agentVersion = input.agentVersion ?? 'unknown'
    const action = input.action ?? 'tool.execute'
    const resource = input.resource ?? { type: 'tool', id: input.toolId }
    const payload = input.payload ?? {
      operationKey: input.operationKey,
      toolId: input.toolId,
      summary: input.summary
    }
    const policyVersion = input.policyVersion ?? this.defaultPolicyVersion
    const existing = await this.findBoundApproval({
      input,
      action,
      resource,
      payload,
      agentVersion,
      policyVersion
    })

    if (existing) return this.toDecision(existing)

    try {
      const created = await this.authority.request({
        tenantId: input.tenantId,
        operatorId,
        agentId: input.agentId,
        agentVersion,
        action,
        resource,
        payload,
        policyVersion,
        correlationId: input.correlationId,
        operationKey: input.operationKey,
        ...(input.executionRef !== undefined
          ? { executionRef: input.executionRef }
          : {}),
        singleUse: true,
        reason: input.summary,
        proposalPayload: payload
      })
      const pending =
        created.status === 'REQUESTED'
          ? await this.authority.submit(
              input.tenantId,
              created.approvalId,
              operatorId
            )
          : created
      return this.toDecision(pending)
    } catch (error) {
      if (!isApprovalBindingUniqueViolation(error)) throw error
      const raced = await this.findBoundApproval({
        input,
        action,
        resource,
        payload,
        agentVersion,
        policyVersion
      })
      if (!raced) throw error
      return this.toDecision(raced)
    }
  }

  private async findBoundApproval(input: {
    input: ApprovalRequest
    action: string
    resource: { type: string; id?: string }
    payload: unknown
    agentVersion: string
    policyVersion: string
  }): Promise<ApprovalRecord | undefined> {
    const candidates = await this.authority.list(input.input.tenantId)
    const matching = candidates
      .filter((record) => record.operationKey === input.input.operationKey)
      .sort((left, right) => right.requestedAt.localeCompare(left.requestedAt))
    const record = matching[0]
    if (!record) return undefined

    if (
      record.agentId !== input.input.agentId ||
      record.agentVersion !== input.agentVersion ||
      record.policyVersion !== input.policyVersion ||
      (input.input.executionRef !== undefined &&
        record.executionRef !== input.input.executionRef) ||
      !approvalMatchesAction(record, {
        action: input.action,
        resource: input.resource,
        payload: input.payload
      })
    ) {
      return {
        ...record,
        status: 'REJECTED',
        decisionReason:
          'Approval binding no longer matches the immutable execution request.'
      }
    }
    return record
  }

  private async beginExecution(
    request: ApprovalExecutionRequest
  ): Promise<ApprovalExecutionHandle> {
    const record = await this.authority.get(
      request.tenantId,
      request.approvalId
    )
    if (
      record.agentId !== request.agentId ||
      record.agentVersion !== request.agentVersion ||
      record.policyVersion !== request.policyVersion ||
      record.executionRef !== request.executionRef ||
      !approvalMatchesAction(record, {
        action: request.action,
        resource: request.resource,
        payload: request.payload
      })
    ) {
      throw new Error('Approval binding no longer matches the execution.')
    }
    const reservation = await this.authority.reserve({
      tenantId: request.tenantId,
      approvalId: request.approvalId,
      action: request.action,
      resource: request.resource,
      payload: request.payload,
      agentId: request.agentId,
      agentVersion: request.agentVersion,
      policyVersion: request.policyVersion,
      operationKey: request.operationKey,
      ownerId: request.executionRef,
      ttlMs: 60_000
    })
    try {
      await this.authority.markExecuting({
        tenantId: request.tenantId,
        approvalId: request.approvalId,
        reservationId: reservation.reservationId
      })
    } catch (error) {
      await Promise.resolve(
        this.authority.release({
          tenantId: request.tenantId,
          approvalId: request.approvalId,
          reservationId: reservation.reservationId,
          evidence: {
            outcome: 'no_effect',
            source: 'adapter',
            evidenceRef: `${request.executionRef}:approval_begin_failed`
          }
        })
      ).catch(() => undefined)
      throw error
    }
    return {
      approvalId: request.approvalId,
      reservationId: reservation.reservationId
    }
  }

  private async completeExecution(input: {
    request: ApprovalExecutionRequest
    reservationId: string
    evidenceRef: string
  }): Promise<void> {
    await this.authority.confirm({
      tenantId: input.request.tenantId,
      approvalId: input.request.approvalId,
      reservationId: input.reservationId,
      evidence: {
        outcome: 'effect_confirmed',
        executionRef: input.request.executionRef,
        evidenceRef: input.evidenceRef
      }
    })
  }

  private async failExecution(input: {
    request: ApprovalExecutionRequest
    reservationId: string
    evidenceRef: string
  }): Promise<void> {
    await this.authority.fail({
      tenantId: input.request.tenantId,
      approvalId: input.request.approvalId,
      reservationId: input.reservationId,
      evidence: {
        outcome: 'no_effect',
        source: 'adapter',
        evidenceRef: input.evidenceRef
      }
    })
  }

  private async markUncertain(input: {
    request: ApprovalExecutionRequest
    reservationId: string
    reason: string
    evidenceRef: string
  }): Promise<void> {
    await this.authority.markUncertain({
      tenantId: input.request.tenantId,
      approvalId: input.request.approvalId,
      reservationId: input.reservationId,
      reason: input.reason,
      evidence: {
        outcome: 'effect_possibly_started',
        evidenceRef: input.evidenceRef
      }
    })
  }

  private toDecision(record: ApprovalRecord): ApprovalDecision {
    const approvalId = record.approvalId as ApprovalId
    const reason =
      record.decisionReason ??
      `Approval ${record.status.toLowerCase()} for ${record.action}.`
    if (record.status === 'APPROVED') {
      return { status: 'APPROVED', approvalId, reason }
    }
    if (record.status === 'REQUESTED' || record.status === 'PENDING') {
      return { status: 'PENDING', approvalId, reason }
    }
    return { status: 'DENIED', approvalId, reason }
  }
}

function isApprovalBindingUniqueViolation(error: unknown): boolean {
  if (!error || typeof error !== 'object') return false
  const candidate = error as { code?: unknown; constraint?: unknown }
  return (
    candidate.code === '23505' &&
    candidate.constraint === 'uq_runtime_approvals_execution_binding'
  )
}

/**
 * Canonical JSON serialization (RFC 8785 subset) used for deterministic
 * payload hashing, approval binding and evidence digests.
 *
 * Rules:
 * - object keys sorted by UTF-16 code units;
 * - arrays keep order, `undefined` becomes `null`;
 * - `undefined` object members are omitted;
 * - numbers must be finite, `-0` serializes as `0`;
 * - only plain objects/null-prototype objects are accepted;
 * - depth and node budgets fail closed.
 */
export const CANONICAL_JSON_MAX_DEPTH = 64
export const CANONICAL_JSON_MAX_NODES = 20_000

export class CanonicalJsonError extends Error {
  readonly code: string

  constructor(code: string, message: string) {
    super(message)
    this.name = 'CanonicalJsonError'
    this.code = code
  }
}

function isPlainObject(value: object): boolean {
  const prototype = Object.getPrototypeOf(value)
  return prototype === Object.prototype || prototype === null
}

export function canonicalizeJson(value: unknown): string {
  let nodes = 0
  const seen = new WeakSet<object>()

  const visit = (input: unknown, depth: number, inArray: boolean): string => {
    nodes += 1
    if (nodes > CANONICAL_JSON_MAX_NODES) {
      throw new CanonicalJsonError(
        'canonical_json_node_limit',
        'Canonical JSON payload exceeded the node budget'
      )
    }
    if (depth > CANONICAL_JSON_MAX_DEPTH) {
      throw new CanonicalJsonError(
        'canonical_json_depth_limit',
        'Canonical JSON payload exceeded the depth budget'
      )
    }

    if (input === null) return 'null'

    switch (typeof input) {
      case 'string':
        return JSON.stringify(input)
      case 'boolean':
        return input ? 'true' : 'false'
      case 'number':
        if (!Number.isFinite(input)) {
          throw new CanonicalJsonError(
            'canonical_json_non_finite_number',
            'Canonical JSON does not allow non-finite numbers'
          )
        }
        return JSON.stringify(input)
      case 'undefined':
        if (inArray) return 'null'
        throw new CanonicalJsonError(
          'canonical_json_unsupported_value',
          'Canonical JSON does not allow top-level undefined'
        )
      case 'bigint':
      case 'function':
      case 'symbol':
        throw new CanonicalJsonError(
          'canonical_json_unsupported_type',
          `Canonical JSON does not support ${typeof input} values`
        )
      case 'object': {
        if (seen.has(input)) {
          throw new CanonicalJsonError(
            'canonical_json_cycle',
            'Canonical JSON does not support cyclic structures'
          )
        }
        seen.add(input)
        try {
          if (Array.isArray(input)) {
            const items = input.map((item) => visit(item, depth + 1, true))
            return `[${items.join(',')}]`
          }
          if (!isPlainObject(input)) {
            throw new CanonicalJsonError(
              'canonical_json_unsupported_object',
              'Canonical JSON only accepts plain objects'
            )
          }
          const record = input as Record<string, unknown>
          const parts: string[] = []
          for (const key of Object.keys(record).sort()) {
            const item = record[key]
            if (item === undefined) continue
            parts.push(
              `${JSON.stringify(key)}:${visit(item, depth + 1, false)}`
            )
          }
          return `{${parts.join(',')}}`
        } finally {
          seen.delete(input)
        }
      }
      default:
        throw new CanonicalJsonError(
          'canonical_json_unsupported_type',
          'Canonical JSON received an unsupported value'
        )
    }
  }

  return visit(value, 0, false)
}

