  lowConfidence: 'clarify' | 'handoff' = 'clarify'
) {
  return AgentConfigSchema.parse({
    persona: { name: 'Luna', role: 'secretary', tone: 'calm' },
    greeting: 'Greeting publicada.',
    promptBlocks: [
      {
        id: 'runtime-safety',
        kind: 'safety',
